+++ b/src/domain/sites.js
@@ -0,0 +1,14 @@
+import { AppError } from "../errors.js";
+
+/** A request-local store context for a known site, sharing data and persistence. */
+export function siteStore(store, site = "main") {
+  if (!store.data.sites.some((s) => s.id === site)) throw new AppError("unknown_site", { id: site });
+  const scoped = Object.create(store);
+  scoped.site = site;
+  return scoped;
+}
+
+/** Whether a location belongs to the selected site (main by default). */
+export function locationInSite(store, location) {
+  return store.data.locations.some((l) => l.id === location && l.site === (store.site ?? "main"));
+}
